import type { R2Storage } from "../storage/r2";
import { detectImageType, storageKeys, storeImage } from "../storage/files";

const DOWNLOAD_TIMEOUT_MS = 60_000;

/**
 * Copies an image generated by OneShotAPI (its URL is temporary) into the carousel's folder of the
 * bucket, and returns its public URL.
 */
export async function storeGeneratedImage(
  files: R2Storage,
  { userId, saasId, carouselId, url }: { userId: string; saasId: string; carouselId: string; url: string },
): Promise<string> {
  const response = await fetch(url, { signal: AbortSignal.timeout(DOWNLOAD_TIMEOUT_MS) });
  if (!response.ok) throw new Error(`Generated image download failed (${response.status})`);

  const bytes = Buffer.from(await response.arrayBuffer());
  const type = detectImageType(bytes);
  if (!type) throw new Error(`Unsupported generated image type: ${response.headers.get("content-type") || "unknown"}`);

  return storeImage(files, storageKeys.carousel(userId, saasId, carouselId), { bytes, type });
}

/** Removes every image of a carousel (deleted by its member, or while it was being generated). */
export function removeCarouselImages(files: R2Storage, { userId, saasId, carouselId }: { userId: string; saasId: string; carouselId: string }) {
  return files.deletePrefix(storageKeys.carousel(userId, saasId, carouselId));
}
